import codecs
assert input() == 'ready'
for encoding in ('utf-7', 'utf-8', 'utf-8-sig', 'utf-16-le', 'utf-16-be', 'utf-32-le', 'utf-32-be'):
    for data in (b'', b'A', b'\xe2\x82\xac', b'\xed\xa0\x80', b'\xef\xbb\xbfA', b'\xff\xfeA\x00', b'\xff\xfe\x00\x00A\x00\x00\x00', b'+IKw-', b'\xff'):
        for errors in ('strict', 'ignore', 'replace', 'surrogatepass', 'surrogateescape', 'backslashreplace'):
            for split in range(len(data) + 1):
                decoder = codecs.getincrementaldecoder(encoding)(errors)
                events = []
                for chunk, final in ((data[:split], False), (data[split:], True)):
                    try:
                        result = ('text', list(map(ord, decoder.decode(chunk, final))))
                    except UnicodeDecodeError as error:
                        result = ('error', error.encoding, error.object, error.start, error.end, error.reason)
                    state = decoder.getstate()
                    events.append((result, state))
                    decoder.setstate(state)
                    assert decoder.getstate() == state
                print(encoding, data, errors, split, events)
                decoder.reset()
                assert decoder.decode(b'', False) == ''
print('done')

